import{Et as e,Ot as t,n,qt as r}from"./chunks/framework.C8R-a4p3.js";var i=JSON.parse(`{"title":"Claude Code — The Planner-Executor","description":"Claude Code: multi-step planning, tool use and codebase-wide edits with surgical precision. The agent behind this very site.","frontmatter":{"title":"Claude Code — The Planner-Executor","description":"Claude Code: multi-step planning, tool use and codebase-wide edits with surgical precision. The agent behind this very site."},"headers":[],"relativePath":"en/agentic/claude-code/index.md","filePath":"en/agentic/claude-code/index.md"}`),a={name:`en/agentic/claude-code/index.md`};function o(n,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[t(`<h1 id="claude-code-—-the-planner-executor" tabindex="-1">Claude Code — The Planner-Executor <a class="header-anchor" href="#claude-code-—-the-planner-executor" aria-label="Permalink to “Claude Code — The Planner-Executor”">​</a></h1><p><strong>Claude Code</strong> is Anthropic&#39;s agentic CLI, and it occupies a specific seat in my workflow: the <strong>planner-executor</strong>. Where other agents shine at speed or scale, Claude Code shines at <em>depth</em> — holding a whole codebase in mind, planning multi-step changes, and executing them with surgical precision across dozens of files.</p><h2 id="what-makes-it-different" tabindex="-1">What makes it different <a class="header-anchor" href="#what-makes-it-different" aria-label="Permalink to “What makes it different”">​</a></h2><ul><li><strong>Plans before it touches code.</strong> For any non-trivial task it produces an explicit plan I can correct — the cheapest possible place to fix a mistake.</li><li><strong>Whole-codebase edits.</strong> Search, understand, then edit coherently — not file-by-file blind patches.</li><li><strong>Tool discipline.</strong> It shows its work: commands run, tests executed, diffs staged.</li><li><strong>Taste.</strong> In practice, its refactors read like a careful senior engineer wrote them, which minimizes my review surface.</li></ul><blockquote><p>This portfolio is a Claude Code build: a full VitePress theme clone adapted to two locales — planned once, reviewed by me, shipped in this shape.</p></blockquote><h2 id="how-i-brief-it" tabindex="-1">How I brief it <a class="header-anchor" href="#how-i-brief-it" aria-label="Permalink to “How I brief it”">​</a></h2><p>The better the plan I can critique, the better the result. So my briefs for Claude Code state the goal, the constraints, the definition of done — and explicitly invite a plan before execution. Then I do what the human is for: I read the plan, attack the weak points, and only then let it run. The pattern is described in <a href="/Usf/en/about/how-i-work/">The Agentic Method</a>.</p><p>Claude Code also plays the integrator role after <a href="/Usf/en/agentic/codex/">Codex</a> fan-outs: reconciling diffs, resolving the overlaps, and running the full suite before anything reaches a branch I care about.</p>`,8)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};